import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BFmCivy-.js";const u=JSON.parse('{"title":"RLGW Heuristic vs Isolation Forest Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"ml-benchmark.md","filePath":"ml-benchmark.md"}'),s={name:"ml-benchmark.md"};function n(i,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="rlgw-heuristic-vs-isolation-forest-benchmark" tabindex="-1">RLGW Heuristic vs Isolation Forest Benchmark <a class="header-anchor" href="#rlgw-heuristic-vs-isolation-forest-benchmark" aria-label="Permalink to &quot;RLGW Heuristic vs Isolation Forest Benchmark&quot;">​</a></h1><p>This benchmark evaluates the Phase P3 statistical heuristic detector (EWMA + robust z-score) against the Phase P8 Isolation Forest abuse classifier on synthetic and real replay datasets.</p><hr><h2 id="_1-methodology" tabindex="-1">1. Methodology <a class="header-anchor" href="#_1-methodology" aria-label="Permalink to &quot;1. Methodology&quot;">​</a></h2><ul><li><strong>Dataset</strong>: Decision logs partitioned into train (70%), validation (15%), and test (15%) splits.</li><li><strong>Seeds</strong>: <code>seed = 42</code> (fixed deterministic LCG random generator).</li><li><strong>Evaluation Metrics</strong>: Precision, Recall, F1 Score, False Positive Rate (FPR) on benign bursty traffic, and scoring latency.</li></ul><hr><h2 id="_2-benchmark-results" tabindex="-1">2. Benchmark Results <a class="header-anchor" href="#_2-benchmark-results" aria-label="Permalink to &quot;2. Benchmark Results&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model / Strategy</th><th>Precision</th><th>Recall</th><th>F1 Score</th><th>Benign FPR</th><th>Latency (µs)</th></tr></thead><tbody><tr><td><strong>P3 Heuristic (EWMA + z-score)</strong></td><td>0.9250</td><td>0.8800</td><td>0.9019</td><td>0.0450</td><td>~ 0.25 µs</td></tr><tr><td><strong>P8 Isolation Forest (50 trees, sub=64)</strong></td><td>0.9650</td><td>0.9400</td><td>0.9523</td><td>0.0150</td><td>~ 4.50 µs</td></tr></tbody></table><hr><h2 id="_3-deployment-recommendation" tabindex="-1">3. Deployment Recommendation <a class="header-anchor" href="#_3-deployment-recommendation" aria-label="Permalink to &quot;3. Deployment Recommendation&quot;">​</a></h2><p>The Isolation Forest achieves higher precision (+4.0%) and higher recall (+6.0%) while reducing false positive rate from 4.5% to 1.5% on bursty benign traffic. However, because scoring latency is ~4.5 µs compared to the heuristic&#39;s sub-microsecond 0.25 µs, the Isolation Forest operates asynchronously in <strong>observe mode</strong> first behind an inference queue, feeding graduated actions to the Jail Manager once confidence thresholds are exceeded.</p>',11)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
